command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "b200291e67823984c9e396a28855348e99b15b3d") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout main
if ($LASTEXITCODE -ne 0) { throw "checkout main failed" }
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "fast-forward main failed" }
if ((git rev-parse HEAD).Trim() -ne "b200291e67823984c9e396a28855348e99b15b3d") { throw "main mismatch" }
python -X utf8 -m py_compile tests\winui\test_remote_windows_task_contract.py
if ($LASTEXITCODE -ne 0) { throw "contract syntax failed" }
python -X utf8 tests\winui\test_remote_windows_task_contract.py
if ($LASTEXITCODE -ne 0) { throw "remote task contract failed" }
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }
git diff --check HEAD^..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "REMOTE_SETTINGS_PRINCIPLES_REFACTOR_PASS"
